import json
import re
import sys

def parse_shuffle_payload(raw_str):
    """
    Safely sanitizes and converts Shuffle's non-standard, multi-line 
    unquoted object string formatting into a structured Python dictionary.
    """
    if not isinstance(raw_str, str):
        return raw_str if isinstance(raw_str, dict) else {}

    raw_str = raw_str.strip()
    if not raw_str or raw_str in ["$exec.all_fields", "EXEC_DATA_PLACEHOLDER"]:
        return {}

    def extract_from_block(block_name, key, text):
        # We split consecutive curly braces into pieces to prevent Shuffle's Liquid engine from crashing
        open_brace = "{"
        close_brace = "}"
        pattern = rf'["\']{block_name}["\']\s*:\s*' + open_brace + open_brace + rf'([^' + close_brace + open_brace + r']+)' + close_brace + close_brace

        block_match = re.search(pattern, text)
        if not block_match:
            return ""
        block_content = block_match.group(1)
        match = re.search(rf'["\']{key}["\']\s*:\s*["\']([^"\']+)["\']', block_content)
        return match.group(1) if match else ""

    def extract_field(key, text):
        match = re.search(rf'["\']{key}["\']\s*:\s*["\']([^"\']+)["\']', text)
        return match.group(1) if match else ""

    def extract_mitre_ids(text):
        found = re.findall(r'["\'](T\d{4}(?:\.\d{3})?)["\']', text)
        return list(set(found)) if found else []

    extracted_data = {
        "rule": {
            "level": extract_field("level", raw_str) or "0",
            "description": extract_field("description", raw_str) or extract_field("title", raw_str) or "Multiple Windows Logon Failures",
            "id": extract_field("rule_id", raw_str) or extract_from_block("rule", "id", raw_str) or "",
            "mitre": {
                "id": extract_mitre_ids(raw_str)
            }
        },
        "agent": {
            "id": extract_from_block("agent", "id", raw_str) or "unknown",
            "name": extract_from_block("agent", "name", raw_str) or "unknown"
        },
        "data": {
            "srcip": extract_field("srcip", raw_str) or extract_field("ipAddress", raw_str) or extract_field("IpAddress", raw_str) or "",
            "dstuser": extract_field("dstuser", raw_str) or extract_field("targetUserName", raw_str) or extract_field("TargetUserName", raw_str) or "",
            "srcuser": extract_field("srcuser", raw_str) or "",
            "hashes": extract_field("hashes", raw_str) or ""
        }
    }
    return extracted_data

def analyze_alert(exec_data):
    alert_data = parse_shuffle_payload(exec_data)

    if not isinstance(alert_data, dict):
        raise ValueError(f"Parsed alert is not a dictionary: {type(alert_data).__name__}")

    rule = alert_data.get("rule", {})
    rule_level = int(rule.get("level", 0))
    rule_desc = rule.get("description", "No description")
    rule_id = str(rule.get("id", ""))

    mitre = rule.get("mitre", {})
    mitre_ids = mitre.get("id", [])

    if isinstance(mitre_ids, str):
        mitre_ids = [mitre_ids]

    agent = alert_data.get("agent", {})
    agent_id = agent.get("id", "unknown")
    agent_name = agent.get("name", "unknown")

    data = alert_data.get("data", {})
    src_ip = data.get("srcip", "")
    target_user = data.get("dstuser", data.get("srcuser", ""))
    file_hash = data.get("hashes", "")

    fallback_map = {
        "60204": ["T1110"], 
        "60122": ["T1110"], 
        "5716": ["T1110"],  
        "5145": ["T1135"],  
        "4624": ["T1078"],  
        "4688": ["T1059"],  
        "4625": ["T1110"]
    }

    if not mitre_ids and rule_id in fallback_map:
        mitre_ids = fallback_map[rule_id]

    mitre_map = {
        "T1110": {
            "action": "IP_BLOCK",
            "target": src_ip,
            "command": "firewall-drop",
            "prompt": f"MITRE T1110 (Brute Force): Block IP {src_ip}?"
        },
        "T1046": {
            "action": "IP_BLOCK",
            "target": src_ip,
            "command": "netsh",
            "prompt": f"MITRE T1046 (Scanning): Block IP {src_ip}?"
        },
        "T1003": {
            "action": "USER_LOCK",
            "target": target_user,
            "command": "disable_ad_user",
            "prompt": f"MITRE T1003 (Credential Dumping): Lock {target_user}?"
        },
        "T1078": {
            "action": "USER_LOCK",
            "target": target_user,
            "command": "disable_ad_user",
            "prompt": f"MITRE T1078 (Valid Accounts): Lock {target_user}?"
        },
        "T1204": {
            "action": "HOST_ISOLATION",
            "target": agent_name,
            "command": "host-isolation",
            "prompt": f"MITRE T1204 (User Execution): Isolate {agent_name}?"
        },
        "T1486": {
            "action": "HOST_ISOLATION",
            "target": agent_name,
            "command": "host-isolation",
            "prompt": f"MITRE T1486 (Ransomware): Isolate {agent_name}?"
        }
    }

    decision = {
        "action": "PASSIVE_LOG",
        "target": "none",
        "command": "none",
        "prompt": "No predefined MITRE containment. Passive logging only."
    }

    for technique in mitre_ids:
        base_technique = technique.split(".")
        if base_technique in mitre_map:
            decision = mitre_map[base_technique]
            break

    return {
        "success": True,
        "action": decision["action"],
        "target": decision["target"],
        "command": decision["command"],
        "prompt": decision["prompt"],
        "agent_id": agent_id,
        "dc_agent_id": "001",
        "srcip": src_ip,
        "username": target_user,
        "file_hash": file_hash,
        "rule_level": rule_level,
        "rule_desc": rule_desc,
        "mitre_ids": ", ".join(mitre_ids)
    }

# ==================================================
# SHUFFLE EXECUTION ENTRY POINT
# ==================================================
if __name__ == "__main__":
    try:
        if len(sys.argv) > 1:
            raw_input_data = sys.argv
        else:
            raw_input_data = 'EXEC_DATA_PLACEHOLDER'.replace('EXEC_DATA_PLACEHOLDER', """$exec.all_fields""")

        analysis_result = analyze_alert(raw_input_data)
        print(json.dumps(analysis_result))
    except Exception as e:
        print(json.dumps({"success": False, "action": "ERROR", "prompt": f"Execution Failure: {str(e)}"}))
